param([string]$BaseUrl='http://127.0.0.1:8080',[int]$Requests=300)
$ErrorActionPreference='Stop';$root=Resolve-Path(Join-Path $PSScriptRoot '..\..');Set-Location $root;$cfg=@{};Get-Content .env|Where-Object{$_-match'^\s*([^#=\s]+)=(.*)$'}|ForEach-Object{$cfg[$matches[1]]=$matches[2].Trim().Trim('"').Trim("'")};$tenant=$cfg.PLATFORM_BOOTSTRAP_TENANT_ID
$token=(Invoke-RestMethod -Method Post "$BaseUrl/api/v1/auth/token" -ContentType application/json -Body(@{username=$cfg.PLATFORM_BOOTSTRAP_USER;password=$cfg.PLATFORM_BOOTSTRAP_PASSWORD}|ConvertTo-Json -Compress)).access_token;$h=@{Authorization="Bearer $token"};$endpoint=[Guid]::NewGuid();$values=@();$commands=@('powershell.exe Get-Service Spooler','cmd.exe /c echo controlled','powershell.exe -NoP -NonInteractive -WindowStyle Hidden -EncodedCommand U3ByaW50MzlDb250cm9sbGVkRml4dHVyZQ==','msiexec.exe /i C:\ProgramData\approved.msi /qn','wscript.exe C:\ProgramData\approved-login.vbs')
for($i=0;$i-lt$Requests;$i++){$id=[Guid]::NewGuid();$cmd=$commands[$i%$commands.Count];$name=$cmd.Split(' ')[0];$body=@{event=@{eventId=$id;tenantId=$tenant;domain='Process';eventTime=[DateTimeOffset]::UtcNow.ToString('o');endpointId=$endpoint;processEntityId="sprint39-perf-$i";entityId="sprint39-perf-$i";fields=@{path="C:\Windows\System32\$name";commandLine=$cmd;processName=$name;parentName='explorer.exe';endpointId=$endpoint.ToString();signed='true';interpreterType=if($name-like'powershell*'){'powershell'}elseif($name-like'cmd*'){'cmd'}else{'none'};encodedArgument=($cmd-like'*-EncodedCommand*').ToString().ToLowerInvariant();suspiciousSwitch=($cmd-like'*-EncodedCommand*').ToString().ToLowerInvariant();hiddenIndicator=($cmd-like'*-WindowStyle Hidden*').ToString().ToLowerInvariant();retrievalIndicator='false';executionIndicator='false';obfuscationIndicator='false';userWritableArgument='false';interpreterNestingDepth='1';urlCount='0';suspiciousSwitchSet=''};evidenceReference="controlled://sprint39/performance/$id";late=$false;incomplete=$false;missingFields=@();quality=@('complete')};productionFindings=$false;mode='DryRun'}|ConvertTo-Json -Depth 10 -Compress;$w=[Diagnostics.Stopwatch]::StartNew();Invoke-RestMethod -Method Post "$BaseUrl/internal/v1/detection-events:evaluate" -Headers $h -ContentType application/json -Body $body|Out-Null;$w.Stop();$values+=$w.Elapsed.TotalMilliseconds}
$s=$values|Sort-Object;function P([double]$p){$s[[math]::Floor(($s.Count-1)*$p)]};$health=(Invoke-RestMethod "$BaseUrl/api/v1/detection-health" -Headers $h).data;$report=[ordered]@{schemaVersion='sprint39-execution-performance.v1';executedAt=[DateTimeOffset]::UtcNow.ToString('o');requests=$Requests;activeRules=69;mode='DryRun';productionFindings=$false;p50Milliseconds=[math]::Round((P .50),2);p95Milliseconds=[math]::Round((P .95),2);p99Milliseconds=[math]::Round((P .99),2);maximumMilliseconds=[math]::Round(($s|Measure-Object -Maximum).Maximum,2);engineHealth=$health;passed=(P .95)-lt250-and(P .99)-lt500};$report|ConvertTo-Json -Depth 10|Set-Content artifacts/sprint39-execution-performance.json -Encoding utf8;$report|ConvertTo-Json -Depth 10;if(-not$report.passed){throw 'Sprint 39 performance budget exceeded.'}
